package com.tamarasdk

import com.tamarasdk.di.AppComponent
import com.tamarasdk.di.AppModule
import com.tamarasdk.di.DaggerAppComponent
import com.tamarasdk.ui.TamaraInformationViewModel
import com.tamarasdk.ui.TamaraPaymentViewModel

internal object DIHelper {
    private lateinit var appComponent: AppComponent
    private fun intComponent() {
        if (!::appComponent.isInitialized) {
            appComponent = DaggerAppComponent.builder()
                .appModule(AppModule())
                .build()
        }
    }

    @JvmStatic
    fun initAppComponent() {
        intComponent()
    }

     fun inject(tamaraPaymentViewModel: TamaraPaymentViewModel) {
        appComponent.inject(tamaraPaymentViewModel)
    }

    fun inject(tamaraInformationViewModel: TamaraInformationViewModel) {
        appComponent.inject(tamaraInformationViewModel)
    }

}